#[derive(Deserialize,Clone)]#[serde(rename_all="camelCase")]struct MovePlanItem{source:String,target:String,expected_size:Option<u64>,expected_modified:Option<u64>}
#[derive(Serialize)]#[serde(rename_all="camelCase")]struct HistoryDetail{transaction_id:String,entries:Vec<JournalEntry>}
#[derive(Serialize)]#[serde(rename_all="camelCase")]struct JournalStats{bytes:u64,records:u64,warning:bool}
#[derive(Serialize)]#[serde(rename_all="camelCase")]struct HistorySnapshot{items:Vec<HistoryItem>,stats:JournalStats}
#[derive(Serialize)]#[serde(rename_all="camelCase")]struct HistoryItem{transaction_id:String,timestamp:u64,planned:u64,moved:u64,undone:u64,failed:u64,undo_failed:u64,can_undo:bool}
